// ── EDIT THIS CONFIG ONCE ─────────────────────────────────
const CONFIG = {
  BACKEND_URL: 'http://host.docker.internal:5001',
  AUTOMATION_API_KEY: 'paste-your-automation-api-key',
  fromEmail: 'offers@mediportbd.com',
  storeName: 'MediportBD',
  storeUrl: 'https://mediportbd.com',
  campaignLimit: 100
};
// ──────────────────────────────────────────────────────────
// Campaign calendar — one campaign per weekday (others skip)
const CAMPAIGNS = {
  1: { segment: 'at_risk', subject: 'We miss you — 10% off your next order', coupon: 'WINBACK10', title: 'Win-back' },
  3: { segment: 'active', subject: 'Complete your lab setup — picks for you', coupon: '', title: 'Cross-sell' },
  5: { segment: 'vip', subject: 'VIP early access: new arrivals before anyone else', coupon: '', title: 'VIP teaser' }
};
// ──────────────────────────────────────────────────────────
const bdt = new Date(Date.now() + 6 * 3600 * 1000);
const dow = bdt.getUTCDay(); // 0=Sun … 6=Sat
const campaign = CAMPAIGNS[dow] || null;
if (!campaign) {
  return []; // no campaign today — workflow ends silently
}
return [{ json: { CONFIG, ...campaign } }];

// Build a personalized email per customer.
const camp = $('Pick Campaign').first().json;
const CONFIG = camp.CONFIG;
const c = $input.item.json;
if (!c.email) {
  return null; // skip customers without email
}
const stats = c.orderStats || {};
const days = stats.daysSinceLastOrder;
let intro;
switch (camp.segment) {
  case 'at_risk':
    intro = `It has been ${days} days since your last order. Stock moves fast in this industry — here is 10% off to welcome you back.`;
    break;
  case 'active':
    intro = `Thanks for being a regular! Based on what clinics like yours reorder, these might be useful next.`;
    break;
  case 'vip':
    intro = `As one of our most valued partners, you get first look at this week's new arrivals${stats.totalSpent ? ` (lifetime value ৳${Number(stats.totalSpent).toLocaleString()})` : ''}.`;
    break;
  default:
    intro = 'A quick note from the MediportBD team.';
}
const html = `
  <div style="font-family:Arial,sans-serif;max-width:560px;margin:auto">
    <h2>${camp.title}: hello ${c.name}</h2>
    <p>${intro}</p>
    ${camp.coupon ? `<p>Use code <b style="background:#fff3cd;padding:2px 8px">${camp.coupon}</b> at checkout.</p>` : ''}
    <p><a href="${CONFIG.storeUrl}" style="background:#0d6efd;color:#fff;padding:12px 28px;text-decoration:none;border-radius:6px;display:inline-block">Browse Products</a></p>
    <p style="color:#888;font-size:12px">You are receiving this as part of the ${camp.title} program. Reply STOP to opt out.</p>
  </div>`;
return { json: { email: c.email, name: c.name, subject: `${CONFIG.storeName}: ${camp.subject}`, html } };

// Backend wraps lists as {success,data:{customers:[...]}}; emit one item per customer.
const r = $input.first().json;
const list = (r.data && Array.isArray(r.data.customers)) ? r.data.customers : [];
if (!list.length) {
  console.log('[Flatten] no customers in response');
}
return list.map(c => ({ json: c }));
